package it.promptstudio;
import android.app.*;import android.os.*;import android.Manifest;import android.content.*;import android.graphics.Color;import android.hardware.Camera;import android.media.*;import android.provider.MediaStore;import android.view.*;import android.widget.*;import java.io.*;
public class MainActivity extends Activity {
 EditText script; SurfaceView preview; ScrollView scroll; TextView prompt,status; Camera camera; MediaRecorder recorder; File output; boolean recording=false,playing=false,front=true; int speed=140,size=28; Handler handler=new Handler(); float fraction=0; long last; String text="";
 Runnable tick=new Runnable(){public void run(){long now=SystemClock.uptimeMillis(); if(playing&&scroll!=null){float words=Math.max(1,text.trim().split("\\s+").length); int distance=Math.max(0,prompt.getHeight()-scroll.getHeight()); fraction+=Math.min(100,now-last)*distance*speed/(60000f*words);scroll.scrollTo(0,(int)fraction);if(fraction>=distance)playing=false;}last=now;handler.postDelayed(this,25);}};
 public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);editor();handler.post(tick);}
 LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(16,24,16,16);l.setBackgroundColor(0xff101827);return l;}
 Button button(String t,LinearLayout l,Runnable r){Button b=new Button(this);b.setText(t);l.addView(b);b.setOnClickListener(v->r.run());return b;}
 void editor(){preview=null; text=getPreferences(0).getString("script",text);LinearLayout l=column();TextView title=new TextView(this);title.setText("Prompt Studio");title.setTextSize(32);l.addView(title);script=new EditText(this);script.setGravity(Gravity.TOP);script.setText(text);script.setHint("Incolla il tuo discorso");l.addView(script,new LinearLayout.LayoutParams(-1,0,1));button("Apri teleprompter",l,()->{text=script.getText().toString();getPreferences(0).edit().putString("script",text).apply();if(checkSelfPermission(Manifest.permission.CAMERA)!=android.content.pm.PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.CAMERA,Manifest.permission.RECORD_AUDIO},1);else studio();});setContentView(l);}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(g.length==2&&g[0]==android.content.pm.PackageManager.PERMISSION_GRANTED&&g[1]==android.content.pm.PackageManager.PERMISSION_GRANTED)studio();else toast("Servono fotocamera e microfono");}
 void studio(){fraction=0;LinearLayout l=column();FrameLayout stage=new FrameLayout(this);l.addView(stage,new LinearLayout.LayoutParams(-1,0,1));preview=new SurfaceView(this);stage.addView(preview,new FrameLayout.LayoutParams(-1,-1));scroll=new ScrollView(this);prompt=new TextView(this);prompt.setText(text+"\n\n\n\n");prompt.setTextColor(Color.WHITE);prompt.setTextSize(size);prompt.setGravity(Gravity.CENTER_HORIZONTAL);prompt.setPadding(12,12,12,60);prompt.setBackgroundColor(0x88000000);scroll.addView(prompt);stage.addView(scroll,new FrameLayout.LayoutParams(-1,dp(210),Gravity.TOP));scroll.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN)playing=false;if(e.getAction()==MotionEvent.ACTION_UP)fraction=scroll.getScrollY();return false;});status=new TextView(this);status.setText("Pronto");l.addView(status);SeekBar s=new SeekBar(this);s.setMax(240);s.setProgress(speed-40);l.addView(s);s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar a,int p,boolean u){speed=p+40;status.setText(speed+" parole/min");}public void onStartTrackingTouch(SeekBar a){}public void onStopTrackingTouch(SeekBar a){}});LinearLayout row=new LinearLayout(this);l.addView(row);button("Play/Pausa",row,()->{fraction=scroll.getScrollY();playing=!playing;last=SystemClock.uptimeMillis();});button("A+",row,()->prompt.setTextSize(size=Math.min(48,size+2)));button("A-",row,()->prompt.setTextSize(size=Math.max(16,size-2)));button("Registra / Stop",l,()->{if(recording)stop();else start();});button("Cambia camera",l,()->{if(!recording){front=!front;closeCamera();openCamera();}});button("Torna allo script",l,()->{if(recording)stop();playing=false;closeCamera();editor();});preview.getHolder().addCallback(new SurfaceHolder.Callback(){public void surfaceCreated(SurfaceHolder h){openCamera();}public void surfaceChanged(SurfaceHolder h,int f,int w,int z){}public void surfaceDestroyed(SurfaceHolder h){if(recording)stop();closeCamera();}});setContentView(l);}
 int dp(int x){return (int)(x*getResources().getDisplayMetrics().density);}
 int cameraId(){Camera.CameraInfo i=new Camera.CameraInfo();for(int n=0;n<Camera.getNumberOfCameras();n++){Camera.getCameraInfo(n,i);if(i.facing==(front?Camera.CameraInfo.CAMERA_FACING_FRONT:Camera.CameraInfo.CAMERA_FACING_BACK))return n;}return 0;}
 void openCamera(){if(camera!=null||preview==null)return;try{camera=Camera.open(cameraId());Camera.CameraInfo i=new Camera.CameraInfo();Camera.getCameraInfo(cameraId(),i);camera.setDisplayOrientation(front?(360-i.orientation)%360:i.orientation);camera.setPreviewDisplay(preview.getHolder());camera.startPreview();}catch(Exception e){closeCamera();toast("Fotocamera non disponibile");}}
 void closeCamera(){if(camera!=null){try{camera.release();}catch(Exception ignored){}camera=null;}}
 void start(){if(camera==null)return;try{output=File.createTempFile("take-",".mp4",getCacheDir());camera.unlock();recorder=new MediaRecorder();recorder.setCamera(camera);recorder.setAudioSource(MediaRecorder.AudioSource.CAMCORDER);recorder.setVideoSource(MediaRecorder.VideoSource.CAMERA);int id=cameraId();int q=CamcorderProfile.hasProfile(id,CamcorderProfile.QUALITY_1080P)?CamcorderProfile.QUALITY_1080P:CamcorderProfile.QUALITY_HIGH;recorder.setProfile(CamcorderProfile.get(id,q));Camera.CameraInfo info=new Camera.CameraInfo();Camera.getCameraInfo(id,info);recorder.setOrientationHint(info.orientation);recorder.setOutputFile(output.getAbsolutePath());recorder.setPreviewDisplay(preview.getHolder().getSurface());recorder.prepare();recorder.start();recording=true;playing=true;last=SystemClock.uptimeMillis();status.setText("● REC");}catch(Exception e){releaseRecorder();closeCamera();openCamera();toast("Registrazione non disponibile: "+e.getMessage());}}
 void releaseRecorder(){if(recorder!=null){recorder.release();recorder=null;}}
 void stop(){playing=false;boolean ok=false;try{recorder.stop();ok=true;}catch(Exception e){toast("Registrazione troppo breve o interrotta");}finally{recording=false;releaseRecorder();closeCamera();}if(ok){android.net.Uri uri=null;try{ContentValues v=new ContentValues();v.put(MediaStore.Video.Media.DISPLAY_NAME,"PromptStudio-"+System.currentTimeMillis()+".mp4");v.put(MediaStore.Video.Media.MIME_TYPE,"video/mp4");v.put(MediaStore.Video.Media.RELATIVE_PATH,"Movies/PromptStudio");v.put(MediaStore.Video.Media.IS_PENDING,1);uri=getContentResolver().insert(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,v);try(InputStream in=new FileInputStream(output);OutputStream out=getContentResolver().openOutputStream(uri)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}v.clear();v.put(MediaStore.Video.Media.IS_PENDING,0);getContentResolver().update(uri,v,null,null);status.setText("Salvato in Galleria");}catch(Exception e){if(uri!=null)getContentResolver().delete(uri,null,null);toast("Salvataggio fallito");}}if(output!=null)output.delete();if(preview!=null&&preview.getHolder().getSurface().isValid())openCamera();}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}protected void onPause(){super.onPause();if(recording)stop();playing=false;closeCamera();}protected void onResume(){super.onResume();if(preview!=null&&preview.isShown()&&preview.getHolder().getSurface().isValid()&&camera==null)openCamera();}protected void onDestroy(){handler.removeCallbacks(tick);closeCamera();super.onDestroy();}
}